  // Xi is fresh in the static environment.
  val subst = toListFromImmutable(h.getStaticParams).map { sp =>
    val srcName = sp.getName
    val dstName = makeFreshName(srcName, env)
    (srcName, dstName)
  }
  alphaRename(subst, h).asInstanceOf[FnHeader]
}

