  if (maybeArg.isNone) return Some(None)
  val arg = maybeArg.get
  val argSpan = NU.getSpan(arg)

  // Make the tuple coercion.
  Some(Some(STupleCoercionInvocation(SExprInfo(argSpan, false, Some(u)),
                                     arg,
                                     u,
                                     coercions,
